program_code='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected background regions and note which reach the edge.
    seen = [[False] * w for _ in range(h)]
    region_id = [[-1] * w for _ in range(h)]
    zero_regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                region_id[y][x] = len(zero_regions)
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                            and not seen[yy][xx]):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            zero_regions.append((cells, touches_edge))

    # A line component enclosing background gets a one-cell colored halo.
    seen1 = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen1[r][c]:
                continue
            q = deque([(r, c)])
            seen1[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1
                            and not seen1[yy][xx]):
                        seen1[yy][xx] = True
                        q.append((yy, xx))

            closed = False
            for y, x in cells:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0:
                        rid = region_id[yy][xx]
                        if rid >= 0 and not zero_regions[rid][1]:
                            closed = True

            if not closed:
                continue
            for y, x in cells:
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0:
                            rid = region_id[yy][xx]
                            out[yy][xx] = 3 if not zero_regions[rid][1] else 2
    return out
'''
